    "Su implementación se financiará con los presupuestos institucionales de las entidades involucradas, sin recursos adicionales del Tesoro Público.*",
    "El Gobierno peruano aprobó la Estrategia Nacional de Ciberseguridad 2026-2030 , un instrumento de política pública que busca fortalecer las capacidades del país para prevenir, detectar y responder a amenazas digitales, proteger la infraestructura crítica y garantizar la continuidad de los servicios públicos esenciales frente a incidentes de seguridad informática."
